// Стандарт С++20:

#include <iostream>
#include <format>
#include <cstdint>
#include <array>                                          // Подключение заголовочного файла для работы с фиксированными контейнерами std::array, которые заменяют опасные сырые массивы;
#include <span>                                           // Подключение заголовочного файла для работы с объектами std::span — безопасными окнами просмотра, которые хранят адрес данных и контролируют границы памяти массива;
#include <iterator>                                       // Подключение заголовочного файла для работы с итераторами, чтобы объект ostream_iterator мог посимвольно передавать отформатированный текст в поток вывода std::cout;

constexpr std::uint8_t ar_size{3};

int main()
{
    constexpr std::array<double, ar_size>wages{10000.0, 20000.0, 30000.0};  // Инициализация массива из 3 элементов. constexpr - дает команду компилятору сначала вычислить объект до того как будет запущена программа. std::array - класс-контейнер, который создает безопасный массив типа double, знает размер, количество элементов массива и защищает программу от случайного переполнения;
    constexpr std::array<int16_t, ar_size>stacks{3, 2, 1};                  // Инициализация массива из 3 элементов. constexpr - дает команду компилятору сначала вычислить объект до того как будет запущена программа. std::array - класс-контейнер, который создает безопасный массив типа int16_t, знает размер, количество элементов массива и защищает программу от случайного переполнения;
    const std::span<const double>pw{wages};                                 // std::span - класс представления (объект pw), который хранит адрес начала массива типа double и количество элементов, сам класс span ничего не хранит, только смотрит на память, где содержится массив wages. Квалификаторы const защищают от изменений как сам объект pw, так и просматриваемые данные;
    const std::span<const int16_t>ps{stacks};                               // std::span - класс представления (объект ps), который хранит адрес начала массива типа int16_t и количество элементов, сам класс span ничего не хранит, только смотрит на память, где содержится массив stacks. Квалификаторы const защищают от изменений как сам объект ps, так и просматриваемые данные;
    std::cout << std::format("pw = {}, *pw = {}\n",                         // Объект cout с помощью оператора << выводит строку с адресом начала массива (1 элемента) и значение 1 элемента массива. Метод класса span .data() возвращает адрес первого элемента массива. Метод класса span .front() возвращает значение первого элемента массива;
               static_cast<const void*>(pw.data()), pw.front());            // static_cast<const void*> - явно преобразует тип указателя в универсальный адрес (void*), чтобы сгенерированная функцией std::format строка вывела его на экран в шестнадцатеричном виде;
    const auto next_pw = pw.subspan(1);               // Создается автоматический тип std::span<const double> подокна для отдельного просмотра значения массива pw. Метод класса span .subspan() берет исходное окно pw и производит шаг в 8 байт (сдвиг на 1 элемент массива). Квалификатор const защищает от случайного изменения адрес подокна;
    std::cout << "Смещение на следующий элемент:\n";
    std::cout << std::format("pw = {}, *pw = {}\n\n",                       // Объект cout с помощью оператора << выводит строку с адресом массива (уже 2 элемента) и значение 2 элемента массива. Метод класса span .data() возвращает адрес второго элемента массива. Метод класса span .front() возвращает значение второго элемента массива;
               static_cast<const void*>(next_pw.data()), next_pw.front());  // static_cast<const void*> - явно преобразует тип указателя в универсальный адрес (void*), чтобы сгенерированная функцией std::format строка вывела его на экран в шестнадцатеричном виде;
    std::cout << std::format("ps = {}, *ps = {}\n",                         // Объект cout с помощью оператора << выводит строку с адресом начала массива (1 элемента) и значение 1 элемента массива. Метод класса span .data() возвращает адрес первого элемента массива. Метод класса span .front() возвращает значение первого элемента массива;
               static_cast<const void*>(ps.data()), ps.front());            // static_cast<const void*> - явно преобразует тип указателя в универсальный адрес (void*), чтобы сгенерированная функцией std::format строка вывела его на экран в шестнадцатеричном виде;
    const auto next_ps = ps.subspan(1);               // Создается автоматический тип подокна std::span<const int16_t> для отдельного просмотра значения массива ps. Метод класса span .subspan() берет исходное окно ps и производит шаг на 2 байта (сдвиг на 1 элемент массива). Квалификатор const защищает от случайного изменения адрес подокна;
    std::cout << "Смещение на следующий элемент:\n";
    std::cout << std::format("ps = {}, *ps = {}\n\n",                       // Объект cout с помощью оператора << выводит строку с адресом массива (уже 2 элемента) и значение 2 элемента массива. Метод класса span .data() возвращает адрес второго элемента массива. Метод класса span .front() возвращает значение второго элемента массива;
               static_cast<const void*>(next_ps.data()), next_ps.front());  // static_cast<const void*> - явно преобразует тип указателя в универсальный адрес (void*), чтобы сгенерированная функцией std::format строка вывела его на экран в шестнадцатеричном виде;
    std::cout << "Доступ через квадратные скобки:\n";
    std::format_to(std::ostream_iterator<char>(std::cout), "stacks[0] = {}, stacks[1] = {}\n", // std::format_to - функция создает готовую строку по шаблону, отформатированные символы сразу отправляются в поток, минуя выделение под них памяти в куче.
               stacks[0], stacks[1]);                                                                    // std::ostream_iterator<char>(std::cout) - объект-переходник ostream_iterator принимает символы из шаблона функции format_to и сразу выводит их на экран с помощью объекта cout;
    std::cout << "Доступ через явные элементы span:\n";
    std::cout << std::format("*stacks = {}, *(stacks + 1) = {}\n",          // Объект cout выводит строку, имитирующую старую нотацию указателей, но со значениями элементов массива stacks[0] и stacks[1].
                stacks[0], stacks[1]);                                      // Т.к. std::array — это класс-контейнер, к нему нельзя применить сырую адресную арифметику (*stacks и stacks+1). Обратиться к элементам можно только через квадратные скобки или span;
    std::cout << std::format("{} байт = размер контейнера wages\n", sizeof(wages)); // Объект cout с помощью оператора << выводит отформатированную строку с размером массива (24 байта);
    std::cout << std::format("{} байт = размер объекта управления (span)\n", sizeof(decltype(pw)));   // Объект cout выводит отформатированную строку с размером объекта управления (16 байт в 64-разрядной ОС).
}                                                                                                     // decltype(pw) преобразуется в тип const std::span<const double>, который использовался при объявлении окна pw. Оператор sizeof видит этот тип и высчитывает размер объекта класса span (8 байт под адрес + 8 байт под количество элементов);



